import React, { createContext, useCallback, useContext, useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Slot } from '@radix-ui/react-slot';
import { drawerStyleKeys, getDrawerState, getDrawerTranslateStyle } from '../lib/core';
import type { DrawerBaseProps, DrawerDirection } from '../lib/core';
import { usePortalContainer, type PortalContainer } from '../portal';
import styles from './drawer.module.scss';

interface DrawerContextValue {
	open: boolean;
	setOpen: (open: boolean) => void;
	close: () => void;
	direction: DrawerDirection;
	modal: boolean;
	titleId: string;
	descriptionId: string;
}

const DrawerContext = createContext<DrawerContextValue | null>(null);

function useDrawerContext(): DrawerContextValue {
	const context = useContext(DrawerContext);
	if (!context) {
		throw new Error('Drawer sub-components must be used within <Drawer>.');
	}
	return context;
}

export interface DrawerProps extends DrawerBaseProps {
	open?: boolean;
	defaultOpen?: boolean;
	onOpenChange?: (open: boolean) => void;
	children?: React.ReactNode;
}

function Drawer({ direction = 'right', modal = true, open, defaultOpen = false, onOpenChange, children }: DrawerProps) {
	const [internalOpen, setInternalOpen] = useState(defaultOpen);
	const onOpenChangeRef = useRef(onOpenChange);

	useEffect(() => {
		onOpenChangeRef.current = onOpenChange;
	});

	const setOpen = useCallback(
		(next: boolean) => {
			if (open === undefined) {
				setInternalOpen(next);
			}

			onOpenChangeRef.current?.(next);
		},
		[open],
	);

	const close = useCallback(() => {
		setOpen(false);
	}, [setOpen]);

	const isOpen = open !== undefined ? open : internalOpen;
	const titleId = useId();
	const descriptionId = useId();

	return <DrawerContext.Provider value={{ open: isOpen, setOpen, close, direction, modal, titleId, descriptionId }}>{children}</DrawerContext.Provider>;
}

Drawer.displayName = 'Drawer';

export interface DrawerTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
	asChild?: boolean;
}

const DrawerTrigger = React.forwardRef<HTMLButtonElement, DrawerTriggerProps>(({ asChild = false, className = '', children, onClick, ...props }, ref) => {
	const context = useDrawerContext();
	const Comp = asChild ? Slot : 'button';

	return (
		<Comp
			ref={ref}
			type={asChild ? undefined : 'button'}
			className={className}
			onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
				onClick?.(event);
				context.setOpen(true);
			}}
			{...props}>
			{children}
		</Comp>
	);
});
DrawerTrigger.displayName = 'DrawerTrigger';

export interface DrawerCloseProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
	asChild?: boolean;
}

const DrawerClose = React.forwardRef<HTMLButtonElement, DrawerCloseProps>(({ asChild = false, className = '', children, onClick, ...props }, ref) => {
	const context = useDrawerContext();
	const Comp = asChild ? Slot : 'button';

	return (
		<Comp
			ref={ref}
			type={asChild ? undefined : 'button'}
			className={className}
			onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
				onClick?.(event);
				context.close();
			}}
			{...props}>
			{children}
		</Comp>
	);
});
DrawerClose.displayName = 'DrawerClose';

export interface DrawerOverlayProps extends React.HTMLAttributes<HTMLDivElement> {}

const DrawerOverlay = React.forwardRef<HTMLDivElement, DrawerOverlayProps>(({ className = '', onClick, ...props }, ref) => {
	const context = useDrawerContext();

	if (!context.open || !context.modal) {
		return null;
	}

	return (
		<div
			ref={ref}
			data-state={getDrawerState(context.open)}
			className={`${styles[drawerStyleKeys.overlay]} ${className}`}
			onClick={(event: React.MouseEvent<HTMLDivElement>) => {
				onClick?.(event);
				context.close();
			}}
			{...props}
		/>
	);
});
DrawerOverlay.displayName = 'DrawerOverlay';

export interface DrawerContentProps extends React.HTMLAttributes<HTMLDivElement> {
	showCloseButton?: boolean;
	container?: PortalContainer;
}

const DrawerContent = React.forwardRef<HTMLDivElement, DrawerContentProps>(({ className = '', showCloseButton = true, container, style, children, ...props }, ref) => {
	const { open, close, direction, modal, titleId, descriptionId } = useDrawerContext();
	const portalContainer = usePortalContainer(container);
	const contentRef = useRef<HTMLDivElement | null>(null);
	const [isVisible, setIsVisible] = useState(false);

	function setContentRef(element: HTMLDivElement | null) {
		contentRef.current = element;

		if (typeof ref === 'function') {
			ref(element);
		} else if (ref) {
			ref.current = element;
		}
	}

	useLayoutEffect(() => {
		if (!open) {
			return;
		}

		const previouslyFocused = document.activeElement as HTMLElement | null;
		const previousOverflow = document.body.style.overflow;
		if (modal) {
			document.body.style.overflow = 'hidden';
		}

		const handleKeyDown = (event: KeyboardEvent) => {
			if (event.key === 'Escape' && modal) {
				close();
				return;
			}

			if (event.key === 'Tab' && modal) {
				const container = contentRef.current;
				if (!container) {
					return;
				}
				const focusables = Array.from(
					container.querySelectorAll<HTMLElement>(
						'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
					),
				).filter((el) => el.getClientRects().length > 0);
				if (focusables.length === 0) {
					event.preventDefault();
					return;
				}
				const first = focusables[0];
				const last = focusables[focusables.length - 1];
				const active = document.activeElement;

				if (event.shiftKey) {
					if (active === first || active === container || !container.contains(active)) {
						event.preventDefault();
						last.focus();
					}
				} else if (active === last || !container.contains(active)) {
					event.preventDefault();
					first.focus();
				}
			}
		};

		document.addEventListener('keydown', handleKeyDown);

		const contentEl = contentRef.current;
		if (contentEl) {
			contentEl.focus();
		}

		return () => {
			document.body.style.overflow = previousOverflow;
			document.removeEventListener('keydown', handleKeyDown);
			previouslyFocused?.focus();
		};
	}, [close, open, modal]);

	useEffect(() => {
		if (!open) {
			return;
		}

		const frame = requestAnimationFrame(() => {
			setIsVisible(true);
		});

		return () => cancelAnimationFrame(frame);
	}, [open]);

	if (!open || !portalContainer) {
		return null;
	}

	return createPortal(
		<>
			{modal && <DrawerOverlay />}
			<div
				ref={setContentRef}
				role="dialog"
				aria-modal={modal ? 'true' : 'false'}
				aria-labelledby={titleId}
				aria-describedby={descriptionId}
				tabIndex={-1}
				data-state={getDrawerState(open)}
				data-direction={direction}
				style={{ transform: isVisible ? '' : getDrawerTranslateStyle(direction), opacity: isVisible ? '' : 0, ...style }}
				className={`${styles[drawerStyleKeys.content]} ${className}`}
				{...props}>
				<div className={styles[drawerStyleKeys.handle]} />
				{children}
				{showCloseButton && (
					<button type="button" aria-label="关闭" className={styles[drawerStyleKeys.close]} onClick={() => close()}>
						<svg
							className={styles[drawerStyleKeys.xIcon]}
							xmlns="http://www.w3.org/2000/svg"
							width="16"
							height="16"
							viewBox="0 0 24 24"
							fill="none"
							stroke="currentColor"
							strokeWidth="2"
							strokeLinecap="round"
							strokeLinejoin="round"
							aria-hidden="true">
							<path d="M18 6 6 18" />
							<path d="m6 6 12 12" />
						</svg>
					</button>
				)}
			</div>
		</>,
		portalContainer,
	);
});
DrawerContent.displayName = 'DrawerContent';

export interface DrawerHeaderProps extends React.HTMLAttributes<HTMLDivElement> {}

const DrawerHeader = React.forwardRef<HTMLDivElement, DrawerHeaderProps>(({ className = '', children, ...props }, ref) => {
	return (
		<div ref={ref} className={`${styles[drawerStyleKeys.header]} ${className}`} {...props}>
			{children}
		</div>
	);
});
DrawerHeader.displayName = 'DrawerHeader';

export interface DrawerFooterProps extends React.HTMLAttributes<HTMLDivElement> {}

const DrawerFooter = React.forwardRef<HTMLDivElement, DrawerFooterProps>(({ className = '', children, ...props }, ref) => {
	return (
		<div ref={ref} className={`${styles[drawerStyleKeys.footer]} ${className}`} {...props}>
			{children}
		</div>
	);
});
DrawerFooter.displayName = 'DrawerFooter';

export interface DrawerTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {}

const DrawerTitle = React.forwardRef<HTMLHeadingElement, DrawerTitleProps>(({ className = '', children, ...props }, ref) => {
	const context = useDrawerContext();

	return (
		<h2 ref={ref} id={context.titleId} className={`${styles[drawerStyleKeys.title]} ${className}`} {...props}>
			{children}
		</h2>
	);
});
DrawerTitle.displayName = 'DrawerTitle';

export interface DrawerDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement> {}

const DrawerDescription = React.forwardRef<HTMLParagraphElement, DrawerDescriptionProps>(({ className = '', children, ...props }, ref) => {
	const context = useDrawerContext();

	return (
		<p ref={ref} id={context.descriptionId} className={`${styles[drawerStyleKeys.description]} ${className}`} {...props}>
			{children}
		</p>
	);
});
DrawerDescription.displayName = 'DrawerDescription';

export { Drawer, DrawerTrigger, DrawerClose, DrawerOverlay, DrawerContent, DrawerHeader, DrawerFooter, DrawerTitle, DrawerDescription };
export default Drawer;

@use '../../../styles/variables/colors' as *;

// 半透明遮罩
.overlay {
	position: fixed;
	inset: 0;
	z-index: $z-modal;
	background-color: var(--tile-drawer-overlay, $overlay);

	&[data-state='open'] {
		animation: drawer-overlay-in $transition-normal;
	}

	&[data-state='closed'] {
		opacity: 0;
	}
}

@keyframes drawer-overlay-in {
	from {
		opacity: 0;
	}

	to {
		opacity: 1;
	}
}

// 抽屉内容面板
.content {
	position: fixed;
	z-index: $z-modal;
	display: flex;
	flex-direction: column;
	background-color: var(--tile-drawer-background, $card);
	color: $card-foreground;
	box-shadow: var(--tile-drawer-shadow, $shadow-lg);
	outline: none;
	transition:
		transform $transition-slow,
		opacity $transition-fast;

	&[data-direction='right'] {
		inset: 0 0 0 auto;
		width: 75%;
		height: 100%;
		max-width: 24rem;
		border-left: 1px solid var(--tile-drawer-border, $border);
	}

	&[data-direction='left'] {
		inset: 0 auto 0 0;
		width: 75%;
		height: 100%;
		max-width: 24rem;
		border-right: 1px solid var(--tile-drawer-border, $border);
	}

	&[data-direction='top'] {
		inset: 0 0 auto 0;
		width: 100%;
		max-height: 80vh;
		border-bottom: 1px solid var(--tile-drawer-border, $border);
	}

	&[data-direction='bottom'] {
		inset: auto 0 0 0;
		width: 100%;
		max-height: 80vh;
		border-top: 1px solid var(--tile-drawer-border, $border);
	}
}

// 顶部 / 底部方向的手柄
.handle {
	margin: $spacing-4 auto 0;
	display: none;
	height: 0.5rem;
	width: 100px;
	flex-shrink: 0;
	border-radius: $radius-full;
	background-color: var(--tile-drawer-handle-background, $muted);
}

.content[data-direction='top'] .handle,
.content[data-direction='bottom'] .handle {
	display: block;
}

// 右上角关闭按钮
.close {
	position: absolute;
	top: $spacing-4;
	right: $spacing-4;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: $spacing-1;
	border: none;
	border-radius: $radius;
	background-color: transparent;
	color: $muted-foreground;
	opacity: 0.7;
	cursor: pointer;
	transition: opacity $transition-fast;
	outline: none;

	&:hover {
		opacity: 1;
	}

	&:focus-visible {
		box-shadow: var(--tile-drawer-close-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	.xIcon {
		width: 1rem;
		height: 1rem;
		pointer-events: none;
	}
}

.header {
	display: flex;
	flex-direction: column;
	gap: $spacing-1_5;
	padding: var(--tile-drawer-header-padding, $spacing-4);
}

.footer {
	margin-top: auto;
	display: flex;
	flex-direction: column;
	gap: $spacing-2;
	padding: var(--tile-drawer-footer-padding, $spacing-4);
}

.title {
	margin: 0;
	font-size: var(--tile-drawer-title-size, $text-base);
	font-weight: $font-semibold;
	line-height: var(--tile-drawer-title-leading, $leading-none);
	color: $foreground;
}

.description {
	margin: 0;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: var(--tile-drawer-description-color, $muted-foreground);
}
